/*
 * <sound/asound.h>: ALSA's raw MIDI part, /dev/snd/midiC1D0: MIDI bytes written to the port play on
 * the General MIDI synthesizer, at MIDI's 31,250 baud. These requests ask about the port and its
 * buffer.
 *
 * Part of the x86 Runtime library, written for the editor in the shape of Linux's own header: the
 * same names, values and layouts, with only what the editor's devices use.
 *
 * Generated by scripts/sim-header/generate.mjs from scripts/sim-header/deviceTable.mjs. Do not edit
 * it: regenerate it.
 */
#ifndef _SOUND_ASOUND_H
#define _SOUND_ASOUND_H

#if !defined(__x86_64__)
#error "This <sound/asound.h> is the x86 one, included in a compilation for another Target"
#endif

#include <linux/types.h>
#include <linux/ioctl.h>
#include <time.h>

/** A version number from its three parts. */
#define SNDRV_PROTOCOL_VERSION(major, minor, subminor) (((major) << 16) | ((minor) << 8) | (subminor))

/* What SNDRV_RAWMIDI_IOCTL_PVERSION answers on the guest's Linux 7.2. */
#define SNDRV_RAWMIDI_VERSION SNDRV_PROTOCOL_VERSION(2, 0, 5)

/* The two directions of a port. */
#define SNDRV_RAWMIDI_STREAM_OUTPUT 0 /* From the program to the synthesizer. */
#define SNDRV_RAWMIDI_STREAM_INPUT  1
#define SNDRV_RAWMIDI_STREAM_LAST   SNDRV_RAWMIDI_STREAM_INPUT

/* snd_rawmidi_info's flags. */
#define SNDRV_RAWMIDI_INFO_OUTPUT 0x1
#define SNDRV_RAWMIDI_INFO_INPUT  0x2
#define SNDRV_RAWMIDI_INFO_DUPLEX 0x4
#define SNDRV_RAWMIDI_INFO_UMP    0x8

/** What SNDRV_RAWMIDI_IOCTL_INFO reads: which card and device the port is, and its names. */
struct snd_rawmidi_info {
    unsigned int device;
    unsigned int subdevice;
    int stream;         /* Which direction to ask about, set before the call. */
    int card;           /* 1 here: the card after the sound card. */
    unsigned int flags; /* SNDRV_RAWMIDI_INFO_*. */
    unsigned char id[64];
    unsigned char name[80];
    unsigned char subname[32];
    unsigned int subdevices_count;
    unsigned int subdevices_avail;
    int tied_device;    /* The device tied to this one, 0 here. */
    unsigned char reserved[60];
};

/* snd_rawmidi_params's mode, for input only. */
#define SNDRV_RAWMIDI_MODE_FRAMING_MASK  (7 << 0)
#define SNDRV_RAWMIDI_MODE_FRAMING_SHIFT 0
#define SNDRV_RAWMIDI_MODE_FRAMING_NONE  (0 << 0)
#define SNDRV_RAWMIDI_MODE_FRAMING_TSTAMP (1 << 0)
#define SNDRV_RAWMIDI_MODE_CLOCK_MASK    (7 << 3)
#define SNDRV_RAWMIDI_MODE_CLOCK_SHIFT   3
#define SNDRV_RAWMIDI_MODE_CLOCK_NONE    (0 << 3)
#define SNDRV_RAWMIDI_MODE_CLOCK_REALTIME (1 << 3)
#define SNDRV_RAWMIDI_MODE_CLOCK_MONOTONIC (2 << 3)
#define SNDRV_RAWMIDI_MODE_CLOCK_MONOTONIC_RAW (3 << 3)

/** What SNDRV_RAWMIDI_IOCTL_PARAMS sets: the size of the port's buffer. */
struct snd_rawmidi_params {
    int stream;
    size_t buffer_size;                 /* The buffer's size in bytes. */
    size_t avail_min;                   /* How much room a write waits for. */
    unsigned int no_active_sensing : 1; /* Do not send Active Sensing at close. */
    unsigned int mode;
    unsigned char reserved[12];
};

/** Padding that puts the next field where a time_t would align it. */
typedef struct {
    unsigned char pad[4];
} __time_pad;

/** What SNDRV_RAWMIDI_IOCTL_STATUS reads: the room in the port's buffer. */
struct snd_rawmidi_status {
    int stream;             /* Which direction to ask about, set before the call. */
    __time_pad pad1;
    struct timespec tstamp; /* When it was asked. */
    size_t avail;           /* Bytes free in the buffer. */
    size_t xruns;
    unsigned char reserved[16];
};

/* The requests. */
/* The protocol version, SNDRV_RAWMIDI_VERSION, into an int. */
#define SNDRV_RAWMIDI_IOCTL_PVERSION _IOR('W', 0x00, int)
/* The port's identity. */
#define SNDRV_RAWMIDI_IOCTL_INFO     _IOR('W', 0x01, struct snd_rawmidi_info)
/* Change the buffer. */
#define SNDRV_RAWMIDI_IOCTL_PARAMS   _IOWR('W', 0x10, struct snd_rawmidi_params)
/* The buffer's state. */
#define SNDRV_RAWMIDI_IOCTL_STATUS   _IOWR('W', 0x20, struct snd_rawmidi_status)
/* Drop the bytes not sent yet; the argument points to the stream. */
#define SNDRV_RAWMIDI_IOCTL_DROP     _IOW('W', 0x30, int)
/* Wait until every byte has been sent; the argument points to the stream. */
#define SNDRV_RAWMIDI_IOCTL_DRAIN    _IOW('W', 0x31, int)

#endif
